-- Libro «The Signal and the Noise» (Nate Silver): correcciones de las lecciones 1, 2, 4, 5, 6, 7, 9 y 10 (las lecciones 3 y 8 y las preguntas ya están aplicadas).
-- Todo o nada: si algún texto no coincide exactamente, lanza «sin coincidencia» y no cambia nada. Antes de ejecutarlo se guardó lo anterior en preguntas_dudosas_log.
do $$ declare n int; begin
update lecciones set conexion_cruzada=replace(conexion_cruzada,'los expertos con acceso a más información y modelos más complejos no predicen mejor que modelos simples calibrados','los expertos prominentes predicen apenas mejor que el azar y los pronosticadores de estilo «zorro», que combinan varias perspectivas, superan a los de estilo «erizo»'), aplicacion_practica=replace(aplicacion_practica,'Silver argumenta que este ejercicio simple revela más sobre tu capacidad predictiva real que cualquier análisis retrospectivo de tus éxitos y fracasos.','Es una forma de comprobar tu capacidad predictiva real sin depender de la memoria selectiva de tus aciertos y fracasos.'), idea_clave='En todo pronóstico los datos mezclan señal y ruido, y el problema es que los humanos vemos patrones donde no los hay; la solución es pensar en probabilidades.', cita_memorable='Más datos no bastan: lo difícil es saber cuáles de ellos significan algo y cuáles solo hacen ruido.' where id='4c906303-74d2-421a-985e-8884d97040af' and libro_id='053b3469-72b9-4cae-bd5b-26fa51376915' and position('los expertos con acceso a más información y modelos más complejos no predicen mejor que modelos simples calibrados' in conexion_cruzada)>0 and position('Silver argumenta que este ejercicio simple revela más sobre tu capacidad predictiva real que cualquier análisis retrospectivo de tus éxitos y fracasos.' in aplicacion_practica)>0; get diagnostics n=row_count; if n<>1 then raise exception 'sin coincidencia: lección %', 1; end if;
update lecciones set cuerpo=replace(cuerpo,'Silver documenta ambos errores en los mercados financieros: los inversores sobrereaccionan a noticias concretas recientes ignorando la distribución histórica de resultados similares, pero también infrareaccionan cuando la evidencia apunta hacia cambios estructurales porque sus modelos previos son demasiado estables.','Estos dos errores se describen en la literatura de psicología del juicio y se han propuesto también para los mercados financieros; no son un hallazgo específico de Silver.'), conexion_cruzada=replace(conexion_cruzada,'El Sistema 2 bayesiano que Silver prescribe es exactamente el mecanismo de corrección del sesgo de representatividad que Kahneman describe.','El pensamiento bayesiano que defiende Silver (partir de la tasa base y ajustarla con la evidencia) es compatible con la corrección que Kahneman propone para este sesgo.'), aplicacion_practica=replace(aplicacion_practica,'Silver argumenta que los malos pronosticadores no actualizan o actualizan de forma asimétrica — solo con la evidencia que confirma la posición previa.','Un sesgo habitual (el sesgo de confirmación) es actualizar solo con la evidencia que confirma la posición previa; registrar las actualizaciones ayuda a detectarlo.'), autocorreccion=replace(autocorreccion,'bajesianismo','bayesianismo'), idea_clave='Pensar como un bayesiano es partir de una probabilidad previa y actualizarla en proporción a la fuerza de la nueva evidencia, sin ignorar ni la tasa base ni los datos nuevos.', cita_memorable='Creer más no es lo mismo que saber más: cada prueba nueva solo debe mover la creencia lo que realmente informa.' where id='881be665-28c6-42fd-9185-2645120b6f26' and libro_id='053b3469-72b9-4cae-bd5b-26fa51376915' and position('Silver documenta ambos errores en los mercados financieros: los inversores sobrereaccionan a noticias concretas recientes ignorando la distribución histórica de resultados similares, pero también infrareaccionan cuando la evidencia apunta hacia cambios estructurales porque sus modelos previos son demasiado estables.' in cuerpo)>0 and position('El Sistema 2 bayesiano que Silver prescribe es exactamente el mecanismo de corrección del sesgo de representatividad que Kahneman describe.' in conexion_cruzada)>0 and position('Silver argumenta que los malos pronosticadores no actualizan o actualizan de forma asimétrica — solo con la evidencia que confirma la posición previa.' in aplicacion_practica)>0 and position('bajesianismo' in autocorreccion)>0; get diagnostics n=row_count; if n<>1 then raise exception 'sin coincidencia: lección %', 2; end if;
update lecciones set cuerpo=replace(cuerpo,'Silver documenta el overfitting en los modelos de riesgo financiero que fallaron en la crisis de 2008: modelos extraordinariamente sofisticados que ajustaban los datos históricos de mercado con gran precisión no contenían variables para escenarios que no habían ocurrido en el período de entrenamiento.','Silver analiza el fallo de las agencias de calificación en la crisis de 2008 (sus modelos asumían, por ejemplo, poca correlación entre impagos hipotecarios y que los precios de la vivienda no caerían a escala nacional) como un caso de modelos apoyados en datos del pasado que no contemplaban escenarios nunca observados; el overfitting propiamente dicho aparece con más claridad en otros capítulos del libro, como los de economía y terremotos.'), conexion_cruzada=replace(conexion_cruzada,'fragililidad','fragilidad'), idea_clave='El overfitting ocurre cuando un modelo aprende el ruido además de la señal: ajusta perfecto el pasado pero falla con datos nuevos, y por eso conviene la parsimonia.', cita_memorable='Un modelo que explica todo el pasado puede estar memorizándolo en vez de entenderlo.' where id='ede64053-9a5d-4b58-a299-7185c7a8b53c' and libro_id='053b3469-72b9-4cae-bd5b-26fa51376915' and position('Silver documenta el overfitting en los modelos de riesgo financiero que fallaron en la crisis de 2008: modelos extraordinariamente sofisticados que ajustaban los datos históricos de mercado con gran precisión no contenían variables para escenarios que no habían ocurrido en el período de entrenamiento.' in cuerpo)>0 and position('fragililidad' in conexion_cruzada)>0; get diagnostics n=row_count; if n<>1 then raise exception 'sin coincidencia: lección %', 4; end if;
update lecciones set cuerpo=replace(replace(cuerpo,'Silver descubre que los scouts de béisbol sufrían sistemáticamente los mismos sesgos que los pronosticadores en otros dominios: sobrereaccionaban a la actuación reciente, ignoraban la regresión a la media, y construían narrativas sobre jugadores que no estaban soportadas por los datos históricos de jugadores comparables.','Silver no concluye que los scouts fueran sistemáticamente peores que las estadísticas: en el libro compara las proyecciones de PECOTA con las listas de prospectos de los scouts (Baseball America) y encuentra que las valoraciones de los scouts aportan información valiosa, de modo que lo más sensato es combinar ambos enfoques.'),'El mercado de apuestas deportivas, con sus mecanismos de corrección de errores por arbitraje, es en algunos sentidos más eficiente que el mercado de evaluación de jugadores porque los errores sistemáticos tienen consecuencias financieras inmediatas que incentivan su corrección.',''), conexion_cruzada=replace(replace(replace(conexion_cruzada,'Ericsson en Peak describe las representaciones mentales de los scouts de béisbol como patrones reconocidos mediante miles de evaluaciones.','Ericsson, en Peak (2016, posterior al libro de Silver), describe las representaciones mentales de los expertos como patrones construidos mediante miles de horas de práctica con feedback.'),'Silver demuestra que esas representaciones pueden ser sistemáticamente erróneas si el feedback que las construyó estaba sesgado.','Silver no desarrolla este argumento; es una lectura de la app: esas representaciones solo son fiables si el feedback que las construyó era válido.'),' feedback válido — y Silver documenta en el béisbol cómo décadas de evaluación de scouts sin feedback sistemático sobre sus errores producía expertise en apariencia sin mejora real en calibración.',' feedback válido.'), aplicacion_practica=replace(aplicacion_practica,'Silver predice que los pronosticadores que establecen el prior histórico antes de analizar el caso específico son sistemáticamente mejor calibrados que los que analizan el caso específico primero.','Establecer el prior histórico antes de analizar el caso específico es una práctica coherente con el enfoque de Silver, aunque el libro no demuestra que mejore la calibración.'), idea_clave='En el deporte la señal es más limpia y el feedback rápido; PECOTA usa jugadores comparables como prior y corrige los sesgos de los scouts, como la regresión a la media.', cita_memorable='Para predecir a alguien, mira primero cómo les fue a los que se le parecen, no solo cómo le fue a él.' where id='c63aaa9d-28c7-4009-b7f1-4da98c439c78' and libro_id='053b3469-72b9-4cae-bd5b-26fa51376915' and position('Silver descubre que los scouts de béisbol sufrían sistemáticamente los mismos sesgos que los pronosticadores en otros dominios: sobrereaccionaban a la actuación reciente, ignoraban la regresión a la media, y construían narrativas sobre jugadores que no estaban soportadas por los datos históricos de jugadores comparables.' in cuerpo)>0 and position('El mercado de apuestas deportivas, con sus mecanismos de corrección de errores por arbitraje, es en algunos sentidos más eficiente que el mercado de evaluación de jugadores porque los errores sistemáticos tienen consecuencias financieras inmediatas que incentivan su corrección.' in cuerpo)>0 and position('Ericsson en Peak describe las representaciones mentales de los scouts de béisbol como patrones reconocidos mediante miles de evaluaciones.' in conexion_cruzada)>0 and position('Silver demuestra que esas representaciones pueden ser sistemáticamente erróneas si el feedback que las construyó estaba sesgado.' in conexion_cruzada)>0 and position(' feedback válido — y Silver documenta en el béisbol cómo décadas de evaluación de scouts sin feedback sistemático sobre sus errores producía expertise en apariencia sin mejora real en calibración.' in conexion_cruzada)>0 and position('Silver predice que los pronosticadores que establecen el prior histórico antes de analizar el caso específico son sistemáticamente mejor calibrados que los que analizan el caso específico primero.' in aplicacion_practica)>0; get diagnostics n=row_count; if n<>1 then raise exception 'sin coincidencia: lección %', 5; end if;
update lecciones set cuerpo=replace(replace(cuerpo,'porque lo considera el modelo más puro disponible de toma de decisiones bajo incertidumbre','porque lo usa como un ejemplo claro de toma de decisiones bajo incertidumbre'),'que Silver considera la competencia cognitiva más importante para el pronóstico en dominios ruidosos','que Silver destaca como una competencia clave para el pronóstico en dominios ruidosos'), conexion_cruzada=replace(replace(replace(replace(conexion_cruzada,'Taleb distingue entre domains where outcomes are ergodic (el promedio de muchas muestras converge al valor esperado) y domains where they are not.','Taleb insiste en que, en dominios con riesgo de ruina, el promedio de muchas repeticiones no basta: una sola pérdida catastrófica puede impedir seguir jugando.'),'El poker, con su estructura de información y valor esperado calculable en cada mano, es ergódico en el largo plazo — el proceso correcto converge al resultado correcto con suficientes manos.','En el póker, con valor esperado calculable en cada mano, el proceso correcto tiende a imponerse con suficientes manos (siempre que el jugador no se arruine antes).'),'Silver implícitamente asume ergodicidad en los dominios que analiza, pero Taleb señalaría que los mercados financieros no son ergódicos porque una sola pérdida catastrófica puede eliminar la posibilidad de jugar las manos futuras.','Es una lectura de la app, no una tesis de Silver, que en los mercados financieros una sola pérdida catastrófica puede eliminar la posibilidad de jugar las manos futuras, un punto que Taleb subraya.'),'La lección del poker sobre proceso versus resultado aplica plenamente en dominios ergódicos pero necesita modificación en dominios con riesgo de ruina.','La lección del póker sobre proceso versus resultado necesita matizarse en dominios con riesgo de ruina.'), autocorreccion=replace(autocorreccion,'Silver idealiza el poker como modelo de decisión bajo incertidumbre más de lo que la evidencia justifica.','El póker es un modelo útil de decisión bajo incertidumbre, pero conviene no idealizarlo.'), aplicacion_practica=replace(aplicacion_practica,'Silver predice que tus mejoras vendrán de mejorar la puntuación de proceso, no de sacar conclusiones de cada resultado individual.','La idea es que la mejora venga de perfeccionar el proceso y no de sacar conclusiones de cada resultado individual.'), idea_clave='El poker enseña a separar la calidad de la decisión del resultado obtenido: con azar de por medio se puede decidir bien y perder, o decidir mal y ganar.', cita_memorable='Una buena decisión puede salir mal y una mala puede salir bien; juzga el proceso, no el desenlace.' where id='e5c70041-da9f-4350-b105-4a55ecac9384' and libro_id='053b3469-72b9-4cae-bd5b-26fa51376915' and position('porque lo considera el modelo más puro disponible de toma de decisiones bajo incertidumbre' in cuerpo)>0 and position('que Silver considera la competencia cognitiva más importante para el pronóstico en dominios ruidosos' in cuerpo)>0 and position('Taleb distingue entre domains where outcomes are ergodic (el promedio de muchas muestras converge al valor esperado) y domains where they are not.' in conexion_cruzada)>0 and position('El poker, con su estructura de información y valor esperado calculable en cada mano, es ergódico en el largo plazo — el proceso correcto converge al resultado correcto con suficientes manos.' in conexion_cruzada)>0 and position('Silver implícitamente asume ergodicidad en los dominios que analiza, pero Taleb señalaría que los mercados financieros no son ergódicos porque una sola pérdida catastrófica puede eliminar la posibilidad de jugar las manos futuras.' in conexion_cruzada)>0 and position('La lección del poker sobre proceso versus resultado aplica plenamente en dominios ergódicos pero necesita modificación en dominios con riesgo de ruina.' in conexion_cruzada)>0 and position('Silver idealiza el poker como modelo de decisión bajo incertidumbre más de lo que la evidencia justifica.' in autocorreccion)>0 and position('Silver predice que tus mejoras vendrán de mejorar la puntuación de proceso, no de sacar conclusiones de cada resultado individual.' in aplicacion_practica)>0; get diagnostics n=row_count; if n<>1 then raise exception 'sin coincidencia: lección %', 6; end if;
update lecciones set cuerpo=replace(replace(cuerpo,'predecían resultados electorales con mayor precisión que la mayoría de los analistas individuales, y los mercados de opciones financieras contienen información sobre la distribución de probabilidades de resultados futuros que los modelos econométricos raramente capturan mejor.','tuvieron en general un buen historial en elecciones, aunque desigual y sin superar siempre a las encuestas bien agregadas.'),'La crisis de 2008 fue el caso de estudio de mercado con error correlacionado masivo: todos los modelos de riesgo de todos los participantes estaban basados en las mismas distribuciones históricas y cometieron el mismo error simultáneamente.','La crisis de 2008 se suele presentar como un caso de error correlacionado masivo: muchos participantes compartían supuestos similares (por ejemplo, que los precios de la vivienda no caerían a la vez en todo el país) y cometieron el mismo error.'), conexion_cruzada=replace(replace(conexion_cruzada,'Hayek en The Sensory Order y en su trabajo sobre los precios como mecanismo de información describe','Hayek en «El uso del conocimiento en la sociedad» (1945) describe'),'Silver proporciona la evidencia empírica moderna de que los mercados de predicción funcionan como Hayek predijo y documenta los casos donde fallan','Silver examina la evidencia sobre el funcionamiento de los mercados de predicción y los casos en que fallan'), autocorreccion=replace(replace(autocorreccion,'Silver es demasiado optimista sobre la eficiencia de los mercados de predicción en dominios complejos.','Conviene no sobreestimar la eficiencia de los mercados de predicción en dominios complejos.'),'exhiben anomalías persistentes (momentum, value premium, volatility clustering) que son difícilmente consistentes con la plena eficiencia','exhiben anomalías documentadas (por ejemplo, momentum o value premium) que algunos autores consideran difíciles de reconciliar con la plena eficiencia'), aplicacion_practica=replace(aplicacion_practica,'hazte la pregunta de Silver:','hazte esta pregunta:'), idea_clave='Los mercados de predicción agregan información dispersa mejor que un experto solo, pero fallan cuando los errores están correlacionados, hay poca liquidez o incentivos torcidos.', cita_memorable='La multitud solo es sabia si cada uno se equivoca a su manera; si todos copian el modelo, se equivocan juntos.' where id='ebd14a7a-04c6-449c-b870-ddf85d278962' and libro_id='053b3469-72b9-4cae-bd5b-26fa51376915' and position('predecían resultados electorales con mayor precisión que la mayoría de los analistas individuales, y los mercados de opciones financieras contienen información sobre la distribución de probabilidades de resultados futuros que los modelos econométricos raramente capturan mejor.' in cuerpo)>0 and position('La crisis de 2008 fue el caso de estudio de mercado con error correlacionado masivo: todos los modelos de riesgo de todos los participantes estaban basados en las mismas distribuciones históricas y cometieron el mismo error simultáneamente.' in cuerpo)>0 and position('Hayek en The Sensory Order y en su trabajo sobre los precios como mecanismo de información describe' in conexion_cruzada)>0 and position('Silver proporciona la evidencia empírica moderna de que los mercados de predicción funcionan como Hayek predijo y documenta los casos donde fallan' in conexion_cruzada)>0 and position('Silver es demasiado optimista sobre la eficiencia de los mercados de predicción en dominios complejos.' in autocorreccion)>0 and position('exhiben anomalías persistentes (momentum, value premium, volatility clustering) que son difícilmente consistentes con la plena eficiencia' in autocorreccion)>0 and position('hazte la pregunta de Silver:' in aplicacion_practica)>0; get diagnostics n=row_count; if n<>1 then raise exception 'sin coincidencia: lección %', 7; end if;
update lecciones set cuerpo=replace(replace(replace(replace(cuerpo,'Silver distingue entre dos dimensiones del pronóstico que frecuentemente se confunden:','Siguiendo la tradición de la meteorología, se distinguen dos dimensiones del pronóstico que frecuentemente se confunden:'),'La calibración es más fundamental que la precisión en dominios estocásticos porque la precisión en cualquier predicción individual puede ser consecuencia del azar, mientras que la calibración sistemática solo puede ser consecuencia de un proceso genuinamente informativo.','En dominios estocásticos la calibración es una condición necesaria: la precisión de una predicción individual puede ser fruto del azar, y la calibración solo se aprecia a lo largo de muchas predicciones. No es suficiente: un pronóstico que siempre repite la frecuencia histórica está calibrado pero no aporta información.'),'Silver documenta que los meteorólogos estadounidenses son los pronosticadores mejor calibrados de cualquier dominio estudiado','Silver destaca que los pronosticadores del Servicio Meteorológico Nacional de EE. UU. están bien calibrados (a diferencia de algunos meteorólogos de televisión locales, que exageran la probabilidad de lluvia) y los cita como uno de los mejores ejemplos de pronóstico'),'y Silver argumenta que debería ser la métrica estándar de evaluación de cualquier sistema de pronóstico','y es una forma habitual de evaluar sistemas de pronóstico probabilístico'), conexion_cruzada=replace(replace(conexion_cruzada,'Los superpronosticadores de Tetlock son los meteorólogos de Tetlock — personas que han desarrollado la disciplina','Los superpronosticadores de Tetlock son personas que han desarrollado la disciplina'),'usa exactamente las mismas métricas de calibración que Silver describe y llega a las mismas conclusiones sobre qué diferencia a los buenos pronosticadores: no es que tengan más conocimiento sino que están mejor calibrados.','(2015, posterior al libro de Silver) evalúa a los pronosticadores con el Brier Score y destaca, como Silver, la importancia de la calibración y de actualizar creencias; Tetlock subraya además rasgos como la apertura mental y el trabajo en equipo.'), aplicacion_practica=replace(aplicacion_practica,'Silver predice que la mayoría de los pronosticadores descubrirán que sus predicciones de alta confianza se materializan con menor frecuencia de la que su confianza sugeriría.','Es frecuente que quien hace este ejercicio descubra que sus predicciones de alta confianza se materializan con menor frecuencia de la que su confianza sugeriría (sobreconfianza).'), idea_clave='La calibración, que la confianza expresada coincida con la frecuencia real de acierto, importa más que la precisión puntual y debería ser la métrica estándar para evaluar pronosticadores.', cita_memorable='Acertar una vez puede ser suerte; estar bien calibrado durante años solo puede ser buen método.' where id='0824a9bd-d49a-4c91-ac72-fdf49304fe16' and libro_id='053b3469-72b9-4cae-bd5b-26fa51376915' and position('Silver distingue entre dos dimensiones del pronóstico que frecuentemente se confunden:' in cuerpo)>0 and position('La calibración es más fundamental que la precisión en dominios estocásticos porque la precisión en cualquier predicción individual puede ser consecuencia del azar, mientras que la calibración sistemática solo puede ser consecuencia de un proceso genuinamente informativo.' in cuerpo)>0 and position('Silver documenta que los meteorólogos estadounidenses son los pronosticadores mejor calibrados de cualquier dominio estudiado' in cuerpo)>0 and position('y Silver argumenta que debería ser la métrica estándar de evaluación de cualquier sistema de pronóstico' in cuerpo)>0 and position('Los superpronosticadores de Tetlock son los meteorólogos de Tetlock — personas que han desarrollado la disciplina' in conexion_cruzada)>0 and position('usa exactamente las mismas métricas de calibración que Silver describe y llega a las mismas conclusiones sobre qué diferencia a los buenos pronosticadores: no es que tengan más conocimiento sino que están mejor calibrados.' in conexion_cruzada)>0 and position('Silver predice que la mayoría de los pronosticadores descubrirán que sus predicciones de alta confianza se materializan con menor frecuencia de la que su confianza sugeriría.' in aplicacion_practica)>0; get diagnostics n=row_count; if n<>1 then raise exception 'sin coincidencia: lección %', 9; end if;
update lecciones set cuerpo=replace(cuerpo,'Silver argumenta que el cambio empieza por el consumidor de pronósticos: si los consumidores aprendieran a evaluar','Una consecuencia razonable de este planteamiento (no una tesis explícita de Silver) es que el cambio empiece por el consumidor de pronósticos: si los consumidores aprendieran a evaluar'), conexion_cruzada=replace(replace(conexion_cruzada,'El pronosticador sobreconfiado que Silver critica es la versión epistémica del hemisferio izquierdo en control total','Por analogía (lectura de la app, no de Silver), el pronosticador sobreconfiado sería la versión epistémica del hemisferio izquierdo en control total'),'exactamente lo que McGilchrist llama la capacidad negativa de Keats','algo cercano a lo que Keats llamó «capacidad negativa»'), aplicacion_practica=replace(aplicacion_practica,'Silver predice que descubrirás que las fuentes más seguidas y más confiadas tienen la peor calibración histórica, y que fuentes menos populares pero más hedgeadas tienen mejor historial predictivo.','Es una hipótesis razonable (apoyada por el trabajo de Tetlock sobre expertos mediáticos), pero no una predicción de Silver, que las fuentes más seguidas y más confiadas tengan peor calibración que otras menos populares y más prudentes.'), idea_clave='El pronosticador honesto expresa la incertidumbre en probabilidades, actualiza con la evidencia y se evalúa con rigor; el cambio debe empezar por quienes consumen los pronósticos.', cita_memorable='Los pronosticadores peores tienen más público porque dicen lo que se quiere oír; premiar la calibración cambiaría eso.' where id='59f445be-1e54-40a8-afe9-ba13d38abdd5' and libro_id='053b3469-72b9-4cae-bd5b-26fa51376915' and position('Silver argumenta que el cambio empieza por el consumidor de pronósticos: si los consumidores aprendieran a evaluar' in cuerpo)>0 and position('El pronosticador sobreconfiado que Silver critica es la versión epistémica del hemisferio izquierdo en control total' in conexion_cruzada)>0 and position('exactamente lo que McGilchrist llama la capacidad negativa de Keats' in conexion_cruzada)>0 and position('Silver predice que descubrirás que las fuentes más seguidas y más confiadas tienen la peor calibración histórica, y que fuentes menos populares pero más hedgeadas tienen mejor historial predictivo.' in aplicacion_practica)>0; get diagnostics n=row_count; if n<>1 then raise exception 'sin coincidencia: lección %', 10; end if;
end $$;
